import{uid,clamp,colors,project,clip,speedAt,timing,sourceOffset,outputOffset,sequence,locate,total,format,sanitize}from'./model.js';
import{renderer}from'./preview.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let P=project(),selected=null,tab='import',engine=false,caps={},time=0,playing=false,raf=0,lastTick=0,urls=new Map(),thumbs=new Map(),history=[],future=[],zoom=1,activeMedia=null,compare=false,busy=false,jobID=null,cancelled=false,saveTimer,toastTimer,scanWorker=null,loading=false,loadedURL='',renderPreview=null;
const video=$('#sourceVideo'),canvas=$('#previewCanvas'),bgmAudio=$('#bgmAudio');let painter;try{painter=renderer(canvas)}catch(e){console.warn(e)}
try{const old=localStorage.getItem('pve.autosave.v1');if(old)P=sanitize(JSON.parse(old))}catch{}
selected=P.clips[0]?.id||null;
const current=()=>P.clips.find(c=>c.id===selected);const mediaOf=c=>P.media.find(m=>m.id===c?.media);const canEdit=()=>!!current()&&!current().gap;const blank=()=>'<p class="small-note">動画を読み込み、タイムラインのクリップを選択してください。</p>';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4400)}
function status(s){$('#statusLine').textContent=s}
function serial(){return JSON.stringify(P)}
function checkpoint(){history.push(serial());if(history.length>60)history.shift();future=[]}
function mutate(fn,redraw=true){checkpoint();fn();renderPreview=null;save();if(redraw)render();else{renderTimeline();draw()}}
function save(){clearTimeout(saveTimer);$('#saveStatus').textContent='SAVING…';saveTimer=setTimeout(async()=>{try{localStorage.setItem('pve.autosave.v1',serial());if(engine)await api('/api/project',P);$('#saveStatus').textContent='AUTOSAVED'}catch(e){$('#saveStatus').textContent='SAVE FAILED';toast('保存に失敗しました。プロジェクトファイルを保存してください。')}},250)}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});if(!r.ok){let d=await r.json().catch(()=>({error:r.statusText}));throw Error(d.error||r.statusText)}return r.json()}
function modal(html){$('#modalContent').innerHTML=html;const d=$('#modal');if(!d.open)d.showModal();$$('[data-close]').forEach(b=>b.onclick=()=>d.close())}
function head(title){return`<div class="modal-top"><h2>${title}</h2><button class="icon-button" data-close aria-label="閉じる">×</button></div>`}
function download(data,name,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
function linkURL(m){return engine?(capsMedia.has(m.id)?(m.proxy?'/cache/'+m.proxy:'/media/'+m.id):null):urls.get(m.id)}
function fit(){const stage=$('#stage'),box=$('#picture');let row=locate(P,time),m=mediaOf(row?.clip)||P.media[0];if(!m)return;let ar=P.aspect==='Original'?(m.width||16)/(m.height||9):P.aspect.split(':').map(Number).reduce((a,b)=>a/b);let w=Math.min(stage.clientWidth,stage.clientHeight*ar);box.style.width=w+'px';box.style.height=w/ar+'px';}
function sourcePosition(){let row=locate(P,time);return row&&!row.clip.gap?Math.min(row.clip.out-.00001,row.clip.in+sourceOffset(Math.max(0,time-row.start),row.clip)):0}
async function seek(t){pause();time=clamp(t,0,total(P));await syncVideo(true);draw();updateClock()}
async function syncVideo(force=false){let row=locate(P,time),c=row?.clip;if(!c)return;if(c.gap){video.pause();draw();return}let m=mediaOf(c),url=m&&linkURL(m);if(!url){video.pause();$('#stageNote').hidden=false;$('#stageNote').textContent='素材を再リンクしてください。保存時と同じ動画を追加すると復帰します。';return}if(activeMedia!==m.id||loadedURL!==url){video.pause();activeMedia=m.id;loadedURL=url;video.src=url;video.load();await new Promise(resolve=>{const f=()=>{video.removeEventListener('loadedmetadata',f);video.removeEventListener('error',f);resolve()};video.addEventListener('loadedmetadata',f,{once:true});video.addEventListener('error',f,{once:true})})}let s=sourcePosition();if(force||Math.abs(video.currentTime-s)>.1){try{video.currentTime=s}catch{}}let speed=localSpeed(row,time-row.start);video.muted=c.audio.mute||speed<.25||speed>4||time-row.start>=timing(c).nodes.at(-1)[1];let fade=1,local=time-row.start,d=timing(c).duration;if(c.audio.fadeIn)fade=Math.min(fade,local/c.audio.fadeIn);if(c.audio.fadeOut)fade=Math.min(fade,(d-local)/c.audio.fadeOut);video.volume=clamp(c.audio.volume*fade,0,1);if(playing&&speed>=.25&&speed<=4&&!video.muted){try{video.playbackRate=speed;await video.play()}catch{}}else if(playing&&speed>=.25&&speed<=4&&local<timing(c).nodes.at(-1)[1]){try{video.playbackRate=speed;await video.play()}catch{}}else video.pause();}
function localSpeed(row,t){let {nodes,pieces}=timing(row.clip);for(let i=1;i<nodes.length;i++)if(t<=nodes[i][1])return pieces[i-1][2];return 0}
function pause(){playing=false;video.pause();bgmAudio.pause();cancelAnimationFrame(raf);$('#play').textContent='▶';$('#play').ariaLabel='再生'}
async function play(){if(!P.clips.length)return;if(playing)return pause();if(time>=total(P)-.01)time=0;playing=true;$('#play').textContent='❚❚';$('#play').ariaLabel='停止';await syncVideo(true);const bg=P.media.find(m=>m.id===P.bgm.media);if(bg&&linkURL(bg)){if(bgmAudio.dataset.media!==bg.id){bgmAudio.src=linkURL(bg);bgmAudio.dataset.media=bg.id}bgmAudio.loop=true;bgmAudio.volume=clamp(P.bgm.volume,0,1);if(Number.isFinite(bgmAudio.duration)&&bgmAudio.duration>0)bgmAudio.currentTime=time%bgmAudio.duration;bgmAudio.play().catch(()=>{})}lastTick=performance.now();raf=requestAnimationFrame(tick)}
let syncing=false;
function tick(now){if(!playing)return;let dt=Math.min(.1,(now-lastTick)/1000);lastTick=now;time+=dt;if(time>=total(P)){time=total(P);pause();draw();updateClock();return}if(!syncing){syncing=true;syncVideo().finally(()=>syncing=false)}let fade=1;if(P.bgm.fadeIn)fade=Math.min(fade,time/P.bgm.fadeIn);if(P.bgm.fadeOut)fade=Math.min(fade,(total(P)-time)/P.bgm.fadeOut);bgmAudio.volume=clamp(P.bgm.volume*fade,0,1);draw();updateClock();raf=requestAnimationFrame(tick)}
function draw(){let row=locate(P,time),c=row?.clip;if(!c)return;$('#picture').style.display='block';$('#emptyState').hidden=true;$('#emptyState').style.display='none';fit();if(c.gap){painter?.black();$('#textOverlay').innerHTML='';return}const m=mediaOf(c);if(!m||!linkURL(m))return;$('#stageNote').hidden=true;try{if(painter)painter.draw(video,c,P.aspect,compare);else{const ctx=canvas.getContext('2d');if(ctx&&video.readyState>=2){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0)}}}catch{}const notes=[];if(m.proxy)notes.push('720p proxy');if(c.stabilization!=='OFF')notes.push('手ぶれ補正は処理プレビューで確認');if(c.interpolation==='blend')notes.push('フレームブレンドは処理プレビューで確認');if(c.speed<.25||c.speed>4)notes.push('極端な速度の試写は近似・原音ミュート');if(!engine&&m.hdr!==false)notes.push('色域・FPSはMac版で確定');if(notes.length){$('#stageNote').hidden=false;$('#stageNote').textContent=notes.join(' · ')}$('#viewerMode').textContent=m.proxy?'SDR PROXY':'ORIGINAL';$('#viewerTitle').textContent=m.name;$('#previewInfo').textContent='GPU · LOOK APPROX.';const scale=$('#picture').clientHeight/1080;$('#textOverlay').innerHTML=P.texts.filter(t=>time>=t.start&&time<=t.end).map(t=>{let opacity=t.opacity;if(t.fade)opacity*=Math.max(0,Math.min(1,(time-t.start)/t.fade,(t.end-time)/t.fade));let align=t.align||'center',transform=align==='left'?'translate(0,-50%)':align==='right'?'translate(-100%,-50%)':'translate(-50%,-50%)';return`<div class="text-item" style="left:${t.x*100}%;top:${t.y*100}%;font-size:${t.size*scale}px;font-family:${t.font==='Serif'?'Georgia':t.font==='Mono'?'monospace':'Arial'};opacity:${opacity};text-align:${align};transform:${transform}">${esc(t.text)}</div>`}).join('')}
video.addEventListener('seeked',draw);video.addEventListener('loadeddata',draw);video.addEventListener('error',()=>{if(video.src)toast('ブラウザで再生できない形式です。Mac版でプロキシを生成してください。')});new ResizeObserver(()=>{fit();draw();renderTimeline()}).observe($('#stage'));
function updateClock(){$('#sourceTime').textContent=format(time);$('#outputDuration').textContent=format(total(P));let width=$('#timelineContent').clientWidth;$('#playhead').style.left=(total(P)?time/total(P)*width:0)+'px'}
function render(){time=clamp(time,0,total(P));$('#projectName').value=P.name;$('#intent').value=P.intent;$('#intentHint').textContent=intentHints[P.intent];$$('.workflow button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('[data-aspect]').forEach(b=>b.classList.toggle('selected',b.dataset.aspect===P.aspect));renderMedia();renderInspector();renderTimeline();draw();updateClock();$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;for(let id of ['setIn','setOut','split','deleteClip','ripple'])$('#'+id).disabled=!current();if(!P.clips.length){$('#picture').style.display='none';$('#emptyState').style.display='flex';$('#viewerTitle').textContent='SOURCE MONITOR';$('#stageNote').hidden=true}}
function renderMedia(){$('#mediaCount').textContent=P.media.filter(m=>m.width).length+' FILES';$('#mediaList').innerHTML=P.media.filter(m=>m.width).map(m=>{let thumb=engine&&m.proxy?`/cache/${m.id}-thumb-0.jpg`:thumbs.get(m.id);return`<button class="media-card ${m.id===current()?.media?'active':''}" data-media="${esc(m.id)}" title="クリックで選択・ダブルクリックで末尾に追加">${thumb?`<img src="${esc(thumb)}" alt="${esc(m.name)}のサムネイル">`:'<div class="media-placeholder">SOURCE VIDEO</div>'}<span class="media-name">${esc(m.name)}</span><small>${m.width} × ${m.height} · ${m.fps?Number(m.fps).toFixed(0)+' FPS':'FPS 未検出'} · ${format(m.duration).slice(3)}</small>${!linkURL(m)?'<span class="relink">再リンクが必要です</span>':''}</button>`}).join('');$$('[data-media]').forEach(b=>{b.onclick=()=>{let c=P.clips.find(c=>c.media===b.dataset.media&&!c.gap);if(c){selected=c.id;seek(sequence(P).find(r=>r.clip.id===c.id).start);render()}else appendMedia(b.dataset.media)};b.ondblclick=()=>appendMedia(b.dataset.media)})}
function appendMedia(id){let m=P.media.find(m=>m.id===id);mutate(()=>{let c=clip(m);P.clips.push(c);selected=c.id});seek(sequence(P).at(-1).start)}
function markersOnTimeline(){let points=[];for(let row of sequence(P)){let c=row.clip;if(c.gap)continue;let analysis=P.analysis.find(a=>a.media===c.media&&a.intent===P.intent);for(let m of analysis?.markers||[])if(m.time>=c.in&&m.time<c.out)points.push({...m,time:row.start+outputOffset(m.time-c.in,c),source:m.time,clip:c.id})}return points}
function renderTimeline(){let rows=sequence(P),dur=total(P),el=$('#timelineContent'),width=Math.max(1,$('#timelineScroll').clientWidth)*zoom;el.style.width=width+'px';$('#timelineCount').textContent=P.clips.length+' CLIPS';$('#timelineEmpty').hidden=!!P.clips.length;let steps=Math.max(4,Math.floor(width/100));$('#ruler').innerHTML=Array.from({length:steps},(_,i)=>`<span style="left:${i/steps*100}%">${format((dur||30)*i/steps).slice(3,8)}</span>`).join('');$('#videoTrack').innerHTML=rows.map(({clip:c,duration:d})=>{let m=mediaOf(c),thumb=m&&(engine&&m.proxy?`/cache/${m.id}-thumb-0.jpg`:thumbs.get(m.id));let strip=m&&engine&&m.proxy?Array.from({length:8},(_,i)=>`<img src="/cache/${m.id}-thumb-${i}.jpg" alt="" loading="lazy">`).join(''):thumb?`<img src="${esc(thumb)}" alt="">`.repeat(Math.min(15,Math.ceil(d/Math.max(dur,1)*width/90))):'';return`<button draggable="true" class="clip-block ${selected===c.id?'selected':''} ${c.gap?'gap':''}" data-clip="${c.id}" style="width:${d/Math.max(dur,.001)*100}%" aria-label="${esc(m?.name||'空白')}"><div class="filmstrip">${strip}</div><span>${c.gap?'GAP':esc(m?.name||'Missing')}</span><small>${c.gap?'':c.speed+'×'+(c.curve!=='constant'?' → '+c.endSpeed+'×':'')+(c.hold?' + HOLD':'')}</small></button>`}).join('');$('#audioTrack').innerHTML=rows.map(({clip:c,duration:d})=>{let m=mediaOf(c);return`<div class="wave-block" style="width:${d/Math.max(dur,.001)*100}%;opacity:${c.gap||c.audio?.mute?.valueOf()?'.2':'.8'}">${m?.audio&&engine&&m.proxy&&!c.gap?`<img src="/cache/${m.id}-wave.png" alt="原音の参照波形。速度変更後の波形ではありません。">`:''}</div>`}).join('');$('#markerTrack').innerHTML=markersOnTimeline().map((m,i)=>`<button class="marker-point ${m.type}" data-marker="${i}" style="left:${m.time/Math.max(dur,.001)*100}%" title="${esc(m.label)} ${format(m.time)}" aria-label="${esc(m.label)} ${format(m.time)}"></button>`).join('');$$('[data-clip]').forEach(b=>{b.onclick=e=>{selected=b.dataset.clip;let r=rows.find(r=>r.clip.id===selected);const t=r.start+((e.clientX-b.getBoundingClientRect().left)/Math.max(b.clientWidth,1))*r.duration;seek(clamp(t,r.start,r.end));renderInspector();renderTimeline()};b.ondragstart=e=>{e.dataTransfer.setData('text/pve-clip',b.dataset.clip)};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();e.stopPropagation();let id=e.dataTransfer.getData('text/pve-clip'),target=b.dataset.clip;if(id&&id!==target)mutate(()=>{let from=P.clips.findIndex(c=>c.id===id),to=P.clips.findIndex(c=>c.id===target),[c]=P.clips.splice(from,1);P.clips.splice(to,0,c)})}});$$('[data-marker]').forEach(b=>b.onclick=()=>showMarker(markersOnTimeline()[+b.dataset.marker]));updateClock()}
const intentHints={'HIGH FASHION':'静止を長く。動きに強いコントラストを。',RAW:'揺れも、不完全な瞬間も残す。',CINEMATIC:'滑らかな時間と、落ち着いた動き。',CLUB:'動きのピークと、短い間隔を拾う。',DOCUMENTARY:'長い間と自然な流れを尊重する。'};
const colorLabels={exposure:'Exposure',contrast:'Contrast',highlights:'Highlights',shadows:'Shadows',whites:'Whites',blacks:'Blacks',temperature:'Temperature',tint:'Tint',saturation:'Saturation',vibrance:'Vibrance'};
function slider(key,label,value,min,max,step=1,unit=''){return`<div class="control-label"><label for="ctl-${key}">${label}</label><output id="out-${key}">${Number(value).toFixed(step<1?2:0)}${unit}</output></div><input type="range" id="ctl-${key}" data-control="${key}" min="${min}" max="${max}" step="${step}" value="${value}">`}
function option(v,text,sel){return`<option value="${v}" ${sel===v?'selected':''}>${text}</option>`}
function selectControl(key,label,value,options){return`<div class="control-label"><label for="ctl-${key}">${label}</label></div><select id="ctl-${key}" data-control="${key}">${options.map(([v,t])=>option(v,t,value)).join('')}</select>`}
function renderInspector(){let c=current(),m=mediaOf(c),b=$('#inspectorBody');$('#inspectorTitle').textContent=tab.toUpperCase();$('#selectionLabel').textContent=c?(c.gap?'GAP':m?.name||'Missing'): '—';let html='';if(tab==='import'){html=`<div class="control-section"><div class="eyebrow">SOURCE LIBRARY</div><h2>${m?esc(m.name):'動画を読み込む'}</h2><p>写真を選ぶように、一瞬を見つける。まずは素材を追加してください。</p><button class="primary wide" id="insImport">＋ 動画を追加</button>${m?`<div class="meta-grid">${[['RESOLUTION',m.width+' × '+m.height],['DURATION',format(m.duration)],['CODEC',m.codec||'Mac版で検出'],['CONTAINER',m.container||'—'],['FRAME RATE',m.fps?m.fps.toFixed(2)+' fps':'未検出'],['TIMING',m.rateMode||'未検出'],['COLOR',m.hdr===null?'未検出':m.hdr?'HDR → SDR':'SDR'],['AUDIO',m.audio===null?'未検出':m.audio?'あり':'なし'],['FILE SIZE',(m.size/1e6).toFixed(1)+' MB'],['ORIENTATION',m.width>m.height?'Landscape':'Portrait']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`:''}</div><div class="control-section"><div class="eyebrow">PROCESSING</div><p class="info-note">${engine?'Mac内のFFmpegで処理します。元素材から720pのSDRプロキシを生成し、書き出しには原本を使います。':'ブラウザ版でカット・ルック・プロジェクト保存を試せます。HEVC/HDRの確定解析、手ぶれ補正、H.264書き出しにはMac版をお使いください。'}</p>${engine&&m?'<button id="prepareAgain" class="wide">プロキシを生成 / 再試行</button>':''}<button id="setupLink" class="wide">${engine?'Macエンジンの情報':'Mac版をダウンロード'} ↗</button></div>`}
else if(tab==='cut'){html=canEdit()?`<div class="control-section"><div class="eyebrow">SOURCE RANGE</div><div class="row"><label>IN <input data-number="in" type="number" min="0" max="${c.out}" step=".01" value="${c.in.toFixed(3)}"></label><label>OUT <input data-number="out" type="number" min="${c.in}" max="${m.duration}" step=".01" value="${c.out.toFixed(3)}"></label></div><p class="small-note">単位：秒。I / O は再生ヘッドの位置へ設定。</p><div class="row"><button id="moveLeft">← 前へ</button><button id="moveRight">後へ →</button></div></div><div class="control-section"><div class="eyebrow">REFRAME</div>${slider('scale','Scale',c.scale,1,3,.01,'×')}${slider('x','Position X',c.x,0,1,.01)}${slider('y','Position Y',c.y,0,1,.01)}<button id="resetCrop" class="wide">中央に戻す</button></div><div class="control-section"><div class="eyebrow">HOLD LAST FRAME</div>${slider('hold','末尾の静止',c.hold||0,0,5,.1,' sec')}<p class="small-note">最後のフレームを保持します。静止区間の原音は無音です。</p></div>`:blank()}
else if(tab==='motion'){html=canEdit()?`<div class="control-section"><div class="eyebrow">TIME SCULPTING</div><div class="speed-hero"><input id="speedNumber" aria-label="速度" type="number" min=".05" max="20" step=".05" value="${c.speed}"><span>×</span></div><div class="preset-grid">${[.05,.1,.25,.5,1,2,4,8,10,20].map(v=>`<button data-speed="${v}" class="${v===c.speed?'selected':''}">${v}×</button>`).join('')}</div><p class="small-note">分割したクリップごとに速度を設定できます。</p>${selectControl('curve','Speed ramp',c.curve,[['constant','Constant'],['linear','Linear'],['ease-in','Ease In'],['ease-out','Ease Out'],['ease-in-out','Ease In / Out']])}${c.curve!=='constant'?slider('endSpeed','End speed',c.endSpeed,.05,20,.05,'×'):''}<canvas id="curveCanvas" class="curve-plot" width="500" height="150" aria-label="速度カーブ"></canvas>${m.fps&&Math.min(c.speed,c.curve==='constant'?c.speed:c.endSpeed)<(+(P.export.fps)||30)/m.fps?`<p class="info-note">${m.fps.toFixed(0)}fps素材では約${((+(P.export.fps)||30)/m.fps).toFixed(2)}×未満でフレームが不足します。</p>`:''}${selectControl('interpolation','Slow motion',c.interpolation,[['duplicate','Frame duplication'],['blend','Frame blending']])}</div><div class="control-section"><div class="eyebrow">STABILIZATION</div>${selectControl('stabilization','補正の強さ',c.stabilization,['OFF','WEAK','MEDIUM','STRONG','HANDHELD','NATURAL','GIMBAL','TRIPOD'].map(v=>[v,v]))}<p class="small-note">強い補正は画角を狭め、端に歪みが出る場合があります。クロップは処理時に自動計算します。事前推定は未対応です。</p><button id="processPreview" class="wide">処理プレビューを生成 ↗</button></div>`:blank()}
else if(tab==='look'){let presets=getPresets();html=canEdit()?`<div class="control-section"><div class="eyebrow">LOOK LIBRARY</div><div class="preset-grid">${Object.keys(presets).map((name,i)=>`<button data-look="${i}">${esc(name)}</button>`).join('')}</div><div class="row"><button id="saveLook">＋ 保存</button><button id="resetLook">リセット</button></div><p class="small-note">GPU試写は近似です。最終色は処理プレビューで確認できます。</p></div><div class="control-section">${Object.entries(colorLabels).map(([k,label])=>slider('color.'+k,label,c.color[k],k==='exposure'?-3:-100,k==='exposure'?3:100,k==='exposure'?.05:1)).join('')}</div><button id="processPreview" class="wide">処理プレビューを生成 ↗</button>`:blank()}
else if(tab==='sound'){html=(canEdit()?`<div class="control-section"><div class="eyebrow">ORIGINAL SOUND</div><label><input type="checkbox" id="muteAudio" ${c.audio.mute?'checked':''}> 原音をミュート</label>${slider('audio.volume','Volume',c.audio.volume,0,2,.01)}${slider('audio.fadeIn','Fade in',c.audio.fadeIn,0,Math.min(5,timing(c).duration/2),.1,' sec')}${slider('audio.fadeOut','Fade out',c.audio.fadeOut,0,Math.min(5,timing(c).duration/2),.1,' sec')}<p class="small-note">1.0を超える音量と速度ランプの原音は、処理プレビューで確認してください。</p></div>`:blank())+`<div class="control-section"><div class="eyebrow">BACKGROUND MUSIC</div><p>${esc(P.media.find(m=>m.id===P.bgm.media)?.name||'BGMを追加すると、全体の長さに合わせてループします。')}</p><button id="addBgm" class="wide">＋ BGMを選択</button>${P.bgm.media?`${slider('bgm.volume','BGM volume',P.bgm.volume,0,2,.01)}${slider('bgm.fadeIn','Fade in',P.bgm.fadeIn||0,0,10,.1,' sec')}${slider('bgm.fadeOut','Fade out',P.bgm.fadeOut||0,0,10,.1,' sec')}<button id="removeBgm" class="wide">BGMを外す</button>`:''}</div>`}
else if(tab==='text'){let t=P.texts[0];html=`<div class="control-section"><div class="eyebrow">TYPOGRAPHY</div><p class="small-note">シーケンス上の秒数で表示区間を指定します。</p>${!t?'<button id="addText" class="wide primary">＋ テキストを追加</button>':`<textarea id="textValue" rows="3" aria-label="表示テキスト">${esc(t.text)}</textarea>${selectControl('text.font','Font',t.font,[['Sans','Sans Serif'],['Serif','Serif'],['Mono','Monospace']])}${selectControl('text.align','Alignment',t.align||'center',[['left','Left'],['center','Center'],['right','Right']])}${slider('text.size','Size',t.size,8,200,1)}${slider('text.x','Position X',t.x,0,1,.01)}${slider('text.y','Position Y',t.y,0,1,.01)}${slider('text.opacity','Opacity',t.opacity,0,1,.01)}${slider('text.fade','Fade',t.fade||0,0,3,.1,' sec')}<div class="row"><label>開始 <input type="number" data-textnum="start" value="${t.start}" min="0" step=".1"></label><label>終了 <input type="number" data-textnum="end" value="${t.end}" min="0" step=".1"></label></div><button id="removeText" class="wide">テキストを削除</button>`}</div>`}
else if(tab==='analyze'){let a=P.analysis.find(a=>a.media===m?.id&&a.intent===P.intent);html=`<div class="control-section"><div class="eyebrow">PHOTOGRAPHER'S EYE</div><h2>強い瞬間を見つける。</h2><p>鮮鋭度、動き、静止、変化の少ない区間を候補として可視化します。</p><button id="scan" class="primary wide" ${!canEdit()?'disabled':''}>✧ 素材をスキャン</button><p class="small-note">顔・視線・ポーズの意味認識は未実装です。画面全体の特徴量から候補を選びます。素材の自動変更はしません。</p>${a?`<p class="small-note">${esc(a.intent)} · ${a.sampleFps.toFixed(1)} samples/sec · ${a.markers.length}候補</p>`:''}</div><div class="control-section"><div class="eyebrow">EDITORIAL RANDOMIZER</div><button id="randomize" class="wide">別の編集思想を引く ↻</button><div id="randomResult"></div></div>${a?`<div class="control-section"><div class="eyebrow">MOMENTS · SOURCE TIME</div>${a.markers.map((m,i)=>`<button class="marker-card ${m.type}" data-analysis="${i}"><strong>${m.label}</strong><span>${m.time.toFixed(2)}s</span><small>${esc(m.detail)}</small></button>`).join('')}</div>`:''}`}
b.innerHTML=html;bindInspector();if(tab==='motion')drawCurve();}
function getPresets(){let defaults={CLEAN:colors(),HARD:{...colors(),contrast:36,blacks:-18,saturation:-8},COLD:{...colors(),temperature:-22,contrast:12},WARM:{...colors(),temperature:20,highlights:-15},RAW:{...colors(),contrast:-8,saturation:-6},NIGHT:{...colors(),exposure:-.4,temperature:-15,blacks:-20},EDITORIAL:{...colors(),contrast:20,shadows:-10,saturation:-18}};try{return{...defaults,...JSON.parse(localStorage.getItem('pve.looks')||'{}')}}catch{return defaults}}
function setPath(path,value){let c=current();if(path.startsWith('color.'))c.color[path.slice(6)]=value;else if(path.startsWith('audio.'))c.audio[path.slice(6)]=value;else if(path.startsWith('bgm.'))P.bgm[path.slice(4)]=value;else if(path.startsWith('text.'))P.texts[0][path.slice(5)]=value;else c[path]=value}
function bindInspector(){const bind=(id,fn)=>{let el=$('#'+id);if(el)el.onclick=fn};bind('insImport',()=>$('#filePicker').click());bind('setupLink',showEngine);bind('prepareAgain',()=>prepareMedia(current().media));bind('moveLeft',()=>move(-1));bind('moveRight',()=>move(1));bind('resetCrop',()=>mutate(()=>Object.assign(current(),{scale:1,x:.5,y:.5})));bind('resetLook',()=>mutate(()=>current().color=colors()));bind('saveLook',()=>{modal(head('ルックを保存')+'<label>プリセット名<input id="lookName" maxlength="30" value="MY LOOK"></label><div class="modal-actions"><button id="confirmLook" class="primary">保存</button></div>');$('#confirmLook').onclick=()=>{let name=$('#lookName').value.trim();if(!name)return;let old=JSON.parse(localStorage.getItem('pve.looks')||'{}');old[name]={...current().color};localStorage.setItem('pve.looks',JSON.stringify(old));$('#modal').close();renderInspector();toast('ルックを保存しました。同じ名前で上書きできます。')}});bind('processPreview',()=>exportProject(true));bind('addBgm',()=>$('#bgmPicker').click());bind('removeBgm',()=>mutate(()=>{P.bgm.media=null;bgmAudio.pause()}));bind('addText',()=>mutate(()=>P.texts.push({id:uid(),text:'UNTITLED',font:'Sans',align:'center',size:48,x:.5,y:.85,opacity:1,fade:.3,start:0,end:Math.max(1,total(P))})));bind('removeText',()=>mutate(()=>P.texts=[]));bind('scan',scan);bind('randomize',randomize);if($('#muteAudio'))$('#muteAudio').onchange=e=>mutate(()=>current().audio.mute=e.target.checked);if($('#speedNumber'))$('#speedNumber').onchange=e=>mutate(()=>current().speed=clamp(e.target.value,.05,20));if($('#textValue'))$('#textValue').onchange=e=>mutate(()=>P.texts[0].text=e.target.value);$$('[data-textnum]').forEach(el=>el.onchange=()=>{let n=clamp(el.value,0,Math.max(total(P),1)),t=P.texts[0];if(el.dataset.textnum==='end'&&n<=t.start)return toast('終了は開始より後にしてください。');if(el.dataset.textnum==='start'&&n>=t.end)return toast('開始は終了より前にしてください。');mutate(()=>t[el.dataset.textnum]=n)});$$('[data-number]').forEach(el=>el.onchange=()=>{let c=current(),m=mediaOf(c),value=clamp(el.value,0,m.duration),key=el.dataset.number;if(key==='in'&&value>=c.out||key==='out'&&value<=c.in)return toast('INはOUTより前にしてください。');mutate(()=>c[key]=value);seek(sequence(P).find(r=>r.clip.id===c.id).start)});$$('[data-speed]').forEach(el=>el.onclick=()=>mutate(()=>current().speed=+el.dataset.speed));$$('[data-look]').forEach(el=>el.onclick=()=>mutate(()=>current().color={...Object.values(getPresets())[+el.dataset.look]}));$$('[data-control]').forEach(el=>{let recorded=false;el.addEventListener('pointerdown',()=>{checkpoint();recorded=true});el.addEventListener('input',()=>{if(!recorded){checkpoint();recorded=true}let value=el.tagName==='SELECT'?el.value:+el.value;setPath(el.dataset.control,value);renderPreview=null;let o=document.getElementById('out-'+el.dataset.control);if(o)o.textContent=Number(value).toFixed(+el.step<1?2:0);draw();drawCurve();renderTimeline();save()});el.addEventListener('change',()=>{recorded=false;renderInspector()})});$$('[data-analysis]').forEach(el=>el.onclick=()=>{let c=current(),a=P.analysis.find(a=>a.media===c.media&&a.intent===P.intent),m=a.markers[+el.dataset.analysis],row=sequence(P).find(r=>r.clip.id===c.id);if(m.time<c.in||m.time>=c.out){toast('この候補は選択クリップのIN / OUT外です。元の範囲へ戻すと編集できます。');return}showMarker({...m,source:m.time,time:row.start+outputOffset(m.time-c.in,c),clip:c.id})})}
function drawCurve(){let el=$('#curveCanvas'),c=current();if(!el||!c)return;let ctx=el.getContext('2d');ctx.clearRect(0,0,500,150);ctx.strokeStyle='#273221';ctx.lineWidth=1;for(let y=25;y<150;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(500,y);ctx.stroke()}ctx.strokeStyle='#d4e59b';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=100;i++){let x=15+i*4.7,s=speedAt(i/100,c),y=132-(Math.log(s/.05)/Math.log(400))*114;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.fillStyle='#859775';ctx.font='18px monospace';ctx.fillText('20×',10,22);ctx.fillText('0.05×',10,145)}
function move(delta){let i=P.clips.findIndex(c=>c.id===selected),j=i+delta;if(j<0||j>=P.clips.length)return;mutate(()=>{[P.clips[i],P.clips[j]]=[P.clips[j],P.clips[i]]});seek(sequence(P).find(r=>r.clip.id===selected).start)}
function splitAtSource(c,s){if(s<=c.in+.001||s>=c.out-.001)return null;let right=structuredClone(c);right.id=uid();let middle=speedAt((s-c.in)/(c.out-c.in),c);right.in=s;right.speed=c.curve==='constant'?c.speed:middle;c.out=s;c.endSpeed=c.curve==='constant'?c.endSpeed:middle;c.hold=0;return right}
function split(){let row=locate(P,time);if(!row||row.clip.gap)return;let s=sourcePosition();if(s<=row.clip.in+.001||s>=row.clip.out-.001)return toast('クリップの途中へ再生ヘッドを移動してください。');mutate(()=>{let i=P.clips.indexOf(row.clip),right=splitAtSource(row.clip,s);P.clips.splice(i+1,0,right);selected=right.id});toast('クリップを分割しました。')}
function trimEdge(edge){let c=current(),row=locate(P,time);if(!c||c.gap||row?.clip.id!==c.id)return toast('選択クリップ内へ再生ヘッドを移動してください。');let t=sourcePosition();if(edge==='in'&&t>=c.out-.001||edge==='out'&&t<=c.in+.001)return;mutate(()=>c[edge]=t);seek(sequence(P).find(r=>r.clip.id===c.id).start)}
function remove(ripple){let c=current();if(!c)return;let i=P.clips.indexOf(c),d=timing(c).duration;mutate(()=>{if(ripple)P.clips.splice(i,1);else P.clips.splice(i,1,{...structuredClone(c),id:uid(),gap:d});selected=P.clips[Math.min(i,P.clips.length-1)]?.id||null});seek(Math.min(time,total(P)))}
function undo(redo=false){let from=redo?future:history,to=redo?history:future;if(!from.length)return;pause();to.push(serial());P=sanitize(JSON.parse(from.pop()));selected=P.clips.find(c=>c.id===selected)?.id||P.clips[0]?.id;save();render();syncVideo(true)}
function showMarker(m){selected=m.clip;seek(m.time);render();let suggestions=P.intent==='RAW'||P.intent==='DOCUMENTARY'?[1,.7,1]:P.intent==='CLUB'?[2,.3,4]:[1,.2,3];modal(head(m.label)+`<p>${esc(m.detail)}</p><p class="mono">SOURCE ${format(m.source)} · ${esc(P.intent)}</p><div class="modal-actions"><button id="markerCut">ここで分割</button>${m.type==='still'?'<button id="markerHold">静止を0.8秒保持</button>':''}${m.type==='motion'||m.type==='best'?`<button id="markerRamp" class="primary">${suggestions.join(' → ')}×</button>`:''}</div><p class="small-note">適用ボタンを押したときだけ編集します。⌘Zで元に戻せます。</p>`);$('#markerCut').onclick=()=>{$('#modal').close();split()};if($('#markerHold'))$('#markerHold').onclick=()=>{mutate(()=>{let c=current(),s=clamp(m.source,c.in+.002,c.out-.002),i=P.clips.indexOf(c),r=splitAtSource(c,s);if(r){c.hold=.8;P.clips.splice(i+1,0,r)}});$('#modal').close()};if($('#markerRamp'))$('#markerRamp').onclick=()=>{mutate(()=>{let c=current(),start=Math.max(c.in,m.source-.6),end=Math.min(c.out,m.source+.6),parts=[],orig=structuredClone(c);if(start>c.in+.001)parts.push({...structuredClone(orig),id:uid(),out:start,hold:0});let mid=clamp(m.source,start+.001,end-.001);parts.push({...structuredClone(orig),id:uid(),in:start,out:mid,speed:suggestions[0],endSpeed:suggestions[1],curve:'ease-out',hold:0});parts.push({...structuredClone(orig),id:uid(),in:mid,out:end,speed:suggestions[1],endSpeed:suggestions[2],curve:'ease-in',hold:0});if(end<c.out-.001)parts.push({...structuredClone(orig),id:uid(),in:end});P.clips.splice(P.clips.indexOf(c),1,...parts);selected=parts.find(c=>c.in===start)?.id});$('#modal').close();toast('速度アクセントを適用しました。')};}
const rules=[['SLOW TENSION','動き出す直前を長く。静止から0.1×へ。'],['HARD CUT','動きの途中で切る。次の画へ余韻を渡す。'],['OFF-BEAT CUT','予想した切り替えから、数フレーム遅らせる。'],['MICRO ZOOM','動かない画へ、小さなクロップの変化を。'],['FREEZE','ポーズが決まる一瞬を、0.8秒だけ留める。'],['LONG SILENCE','音を引いて、服と視線の動きに集中する。'],['ABRUPT SPEED','静けさの直後に8×。速度の段差を残す。'],['REVERSE MOMENT','逆再生に似合う動きを探す。V1は提案のみ。'],['EXTREME CROP','顔から離れ、手・布・影のひとつを選ぶ。'],['ASYMMETRIC RHYTHM','長・短・短・長。均等な尺から外れる。']];let lastRule=-1;
function randomize(){let n;do{n=Math.floor(Math.random()*rules.length)}while(n===lastRule);lastRule=n;let[t,d]=rules[n];$('#randomResult').innerHTML=`<div class="random-card"><strong>${t}</strong><p>${d}</p></div><p class="small-note">提案のみ。素材には適用していません。</p>`}
async function metadata(file,url){let v=document.createElement('video');v.preload='metadata';v.src=url;await new Promise((resolve,reject)=>{v.onloadedmetadata=resolve;v.onerror=()=>reject(Error('この動画はブラウザで読めません。Mac版へ読み込んでください。'))});let m={id:uid(),name:file.name,duration:v.duration,width:v.videoWidth,height:v.videoHeight,size:file.size,fps:null,rateMode:'未検出',codec:null,container:file.name.split('.').at(-1).toUpperCase(),hdr:null,audio:null};if(!Number.isFinite(m.duration)||m.duration<=0)throw Error('動画の長さを取得できません。Mac版で読み込んでください。');try{v.currentTime=Math.min(.1,m.duration/2);await new Promise(r=>v.onseeked=r);let canvas=document.createElement('canvas');canvas.width=160;canvas.height=90;canvas.getContext('2d').drawImage(v,0,0,160,90);thumbs.set(m.id,canvas.toDataURL('image/jpeg',.7))}catch{}v.removeAttribute('src');v.load();return m}
function xhrUpload(file){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/upload');x.setRequestHeader('X-Filename',encodeURIComponent(file.name));x.upload.onprogress=e=>{if(e.lengthComputable)progress('Mac内に素材を読み込み中',e.loaded/e.total)};x.onload=()=>{try{let d=JSON.parse(x.responseText);x.status===200?resolve(d):reject(Error(d.error))}catch{reject(Error('読み込みに失敗しました。'))}};x.onerror=()=>reject(Error('Macエンジンへの接続が切れました。'));x.onabort=()=>reject(Error('読み込みをキャンセルしました。'));$('#cancelJob').onclick=()=>{cancelled=true;x.abort()};x.send(file)})}
async function importFiles(files,isBgm=false){if(busy)return toast('現在の処理が終わるまでお待ちください。');pause();busy=true;cancelled=false;progressModal('素材を読み込み中');try{for(let file of files){if(cancelled)break;let m,url;if(engine)m=await xhrUpload(file);else{url=URL.createObjectURL(file);if(isBgm){let a=new Audio(url);await new Promise((r,j)=>{a.onloadedmetadata=r;a.onerror=()=>j(Error('音声を読み込めません。'))});m={id:uid(),name:file.name,duration:a.duration,width:0,height:0,audio:true,size:file.size};a.removeAttribute('src');a.load()}else m=await metadata(file,url)}let missing=P.media.find(old=>old.name===m.name&&old.size===m.size&&(!linkURL(old)||engine&&!capsMedia.has(old.id)));checkpoint();if(missing){let oldId=missing.id;if(engine){for(let c of P.clips)if(c.media===oldId)c.media=m.id;if(P.bgm.media===oldId)P.bgm.media=m.id;P.analysis=P.analysis.filter(a=>a.media!==oldId);P.media.splice(P.media.indexOf(missing),1,m)}else{m.id=oldId;Object.assign(missing,m);urls.set(m.id,url)}}else{P.media.push(m);if(url)urls.set(m.id,url);if(isBgm)P.bgm.media=m.id;else{let c=clip(m);P.clips.push(c);selected=c.id}}if(engine){capsMedia.add(m.id);if(m.width){try{let r=await api('/api/prepare',{media:m.id});let prepared=await watchJob(r.job);Object.assign(m,prepared)}catch(e){toast('プロキシ生成: '+e.message);status('原本は保存済み。IMPORTからプロキシ生成を再試行できます。')}}}save();render()}$('#modal').close();if(P.clips.length){let row=sequence(P).find(r=>r.clip.id===selected);await seek(row?.start||0)}toast('素材を読み込みました。')}catch(e){$('#modal').close();toast(e.message)}finally{busy=false;jobID=null;$('#filePicker').value='';$('#bgmPicker').value=''}}
function progressModal(title){modal(`<div class="modal-top"><h2>${esc(title)}</h2></div>`+'<div class="progress-track"><div id="progressBar"></div></div><div id="progressLabel" class="progress-caption">準備中…</div><div class="modal-actions"><button id="cancelJob">キャンセル</button></div>');$('#cancelJob').onclick=()=>{cancelled=true;if(jobID)api('/api/cancel',{job:jobID}).catch(()=>{});};}
function progress(operation,value){if($('#progressBar'))$('#progressBar').style.width=clamp(value*100,0,100)+'%';if($('#progressLabel'))$('#progressLabel').textContent=operation+' · '+Math.round(value*100)+'%';status(operation)}
async function watchJob(id){jobID=id;while(true){if(cancelled)await api('/api/cancel',{job:id}).catch(()=>{});let j=await api('/api/job/'+id);progress(j.operation,j.progress);if(j.status==='done'){jobID=null;return j.result}if(j.status==='error'||j.status==='cancelled'){jobID=null;throw Error(j.error||'処理を中止しました。')}await new Promise(r=>setTimeout(r,500))}}
async function prepareMedia(id){if(busy)return;busy=true;cancelled=false;progressModal('プロキシを生成');try{let r=await api('/api/prepare',{media:id}),m=await watchJob(r.job);Object.assign(P.media.find(m=>m.id===id),m);save();render();await syncVideo(true);$('#modal').close()}catch(e){errorModal(e)}finally{busy=false;jobID=null}}
function errorModal(e){modal(head('処理を完了できませんでした')+'<p>編集内容は保持されています。設定や素材を確認して、もう一度お試しください。</p><pre class="code-box">'+esc(e.message)+'</pre><div class="modal-actions"><button data-close>閉じる</button></div>');status('処理に失敗しました。プロジェクトは保持しています。')}
async function scan(){if(busy||!canEdit())return;pause();busy=true;cancelled=false;let c=current(),m=mediaOf(c);progressModal('素材を解析');try{let result;if(engine){let r=await api('/api/analyze',{media:m.id,intent:P.intent});result=await watchJob(r.job)}else{let url=linkURL(m);if(!url)throw Error('元動画を再リンクしてください。');const v=document.createElement('video');v.preload='auto';v.muted=true;v.src=url;const cv=document.createElement('canvas');cv.width=cv.height=64;const ctx=cv.getContext('2d',{willReadFrequently:true});scanWorker=new Worker('analysis-worker.js');const ask=(d,transfer=[])=>new Promise((r,j)=>{scanWorker.onmessage=e=>r(e.data);scanWorker.onerror=e=>j(Error(e.message));scanWorker.postMessage(d,transfer)});try{await new Promise((r,j)=>{v.onloadeddata=r;v.onerror=()=>j(Error('解析用の動画を読み込めません。'))});await ask({type:'reset'});let sampleFps=Math.min(4,1800/m.duration),n=Math.max(1,Math.ceil(m.duration*sampleFps));for(let i=0;i<n;i++){if(cancelled)throw Error('解析をキャンセルしました。');let t=Math.min(m.duration-.001,(i+.1)/sampleFps);if(Math.abs(v.currentTime-t)>.0001){await new Promise((r,j)=>{const timeout=setTimeout(()=>j(Error('フレーム読み込みがタイムアウトしました。')),20000);v.onseeked=()=>{clearTimeout(timeout);r()};v.currentTime=t})}ctx.drawImage(v,0,0,64,64);let image=ctx.getImageData(0,0,64,64);await ask({type:'frame',time:t,buffer:image.data.buffer},[image.data.buffer]);progress('動き・静止・鮮鋭度を解析中',i/n)}result=await ask({type:'finish',media:m.id,intent:P.intent,duration:m.duration,sampleFps})}finally{scanWorker?.terminate();scanWorker=null;v.removeAttribute('src');v.load()}}delete result.samples;mutate(()=>{P.analysis=P.analysis.filter(a=>a.media!==m.id||a.intent!==P.intent);P.analysis.push(result)});$('#modal').close();toast(result.markers.length+'個の候補を表示しました。素材は変更していません。')}catch(e){errorModal(e)}finally{busy=false;jobID=null}}
function showEngine(){if(engine){modal(head('Macエンジン')+`<p>動画はMacの中だけで処理されます。</p><div class="meta-grid">${[['ENGINE',caps.engine],['H.264',caps.ready?'利用可能':'未対応'],['STABILIZER',caps.stabilization?'vidstab':'未導入'],['HDR → SDR',caps.hdr?'利用可能':'未対応']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="small-note">${esc(caps.version)}</p><p>終了は起動したターミナルで Control+C。元素材のコピー・プロキシ・書き出しはMac内に保存されます。保存先と削除手順はREADMEに記載しています。</p>`);return}modal(head('Macで、フル機能を使う')+`<p>同じ編集画面をMac上で起動します。動画はMacから外へ送信されません。</p><ol><li><p>Mac版をダウンロードし、ZIPを展開します。</p></li><li><p>初回のみ Python 3 と FFmpeg が必要です。Homebrew導入済みの場合：</p><pre class="code-box">brew install python ffmpeg-full</pre></li><li><p>展開したフォルダの <strong>Launch.command</strong> を開きます。起動できない場合は同梱READMEをご確認ください。</p></li></ol><p class="small-note">手ぶれ補正にはlibvidstab対応のFFmpegが必要です。起動後に対応状況を確認できます。現在の編集は「保存」で.projectへ書き出し、Mac版で開いて同じ動画を再リンクしてください。</p><a class="primary download-link" href="personal-video-editor-mac.zip" download>Mac版をダウンロード ↓</a>`)}
function exportDialog(){if(!P.clips.length)return toast('動画を追加してください。');const ex=P.export;modal(head('EXPORT')+`<p class="mono">${esc(P.name)} · ${format(total(P))}</p><div class="modal-fields"><label>Destination<select id="exportPreset">${['INSTAGRAM REELS','INSTAGRAM STORIES','INSTAGRAM FEED','YOUTUBE','CUSTOM'].map(v=>option(v,v,ex.preset)).join('')}</select></label><label>Resolution<select id="exportResolution">${['1080p','4K','Source'].map(v=>option(v,v,ex.resolution)).join('')}</select></label><label>Frame rate<select id="exportFps">${['Source','24','30','60'].map(v=>option(v,v,ex.fps)).join('')}</select></label><label>Quality<select id="exportQuality">${['Preview','Standard','High','Maximum'].map(v=>option(v,v,ex.quality)).join('')}</select></label></div><p class="small-note">H.264 / AAC · SDR Rec.709 · MP4<br>Source FPSはSNS互換性を優先し最大60fps。画角プリセットを選ぶとシーケンスの比率も変更します。</p><div class="modal-actions"><button data-close>戻る</button><button id="startExport" class="primary">${engine?'MP4を書き出す':'Mac版で書き出す'} ↗</button></div>`);$('#startExport').onclick=()=>{mutate(()=>{P.export={preset:$('#exportPreset').value,resolution:$('#exportResolution').value,fps:$('#exportFps').value,quality:$('#exportQuality').value};const r={'INSTAGRAM REELS':'9:16','INSTAGRAM STORIES':'9:16','INSTAGRAM FEED':'4:5',YOUTUBE:'16:9'}[P.export.preset];if(r)P.aspect=r});exportProject(false)}}
async function exportProject(preview){if(!engine){showEngine();return}if(busy)return toast('現在の処理が終わるまでお待ちください。');if(!P.clips.length)return;busy=true;cancelled=false;pause();progressModal(preview?'処理プレビュー':'MP4書き出し');try{const r=await api('/api/render',{project:P,preview}),result=await watchJob(r.job);modal(head(preview?'処理プレビュー':'書き出し完了')+`<video controls playsinline src="${esc(result.url)}" style="width:100%;max-height:50vh;background:#000"></video><p class="mono">${result.width} × ${result.height} · ${result.fps} FPS · ${format(result.duration)}</p><a class="primary download-link" href="${esc(result.url)}" download="${esc(P.name.replace(/[^\p{L}\p{N} _-]/gu,'_'))}.mp4">MP4を保存 ↓</a><p class="small-note">${preview?'処理プレビューは540pです。カラー・音声・補間・手ぶれ補正を含みます。':'元素材は変更していません。'}</p>`);status(preview?'処理プレビューを生成しました。':'MP4を書き出しました。')}catch(e){errorModal(e)}finally{busy=false;jobID=null}}
function saveFile(){P.name=$('#projectName').value.trim()||'Untitled film';download(JSON.stringify(P,null,2),P.name.replace(/[^\p{L}\p{N} _-]/gu,'_')+'.project');save();toast('プロジェクトを保存しました。動画ファイルは別途保持してください。')}
function openDialog(){if(engine){api('/api/projects').then(list=>{modal(head('プロジェクトを開く')+`<button id="fromFile" class="wide primary">.project ファイルを開く</button>${list.map((p,i)=>`<button class="project-option" data-project-index="${i}">${esc(p.name)}</button>`).join('')}`);$('#fromFile').onclick=()=>$('#projectPicker').click();$$('[data-project-index]').forEach(b=>b.onclick=async()=>{try{let p=await api('/api/project/'+list[+b.dataset.projectIndex].id);loadProject(p);$('#modal').close()}catch(e){toast(e.message)}})}).catch(e=>toast(e.message))}else $('#projectPicker').click()}
function loadProject(p){pause();let next=sanitize(p);checkpoint();P=next;selected=P.clips[0]?.id;time=0;activeMedia=null;save();render();syncVideo(true);toast('プロジェクトを開きました。未接続の素材は同じ動画を追加して再リンクできます。')}
const capsMedia=new Set();
async function boot(){if(location.hostname==='127.0.0.1'||location.hostname==='localhost'){try{caps=await api('/api/health');engine=!!caps.ready;let medias=await api('/api/media');for(let m of medias)capsMedia.add(m.id);for(let m of P.media){let actual=medias.find(x=>x.id===m.id);if(actual)Object.assign(m,actual)}if(engine){$('#engineButton').textContent='MAC ENGINE';$('#engineButton').classList.add('connected')}else toast(caps.error||'FFmpegが準備できていません。')}catch(e){toast('Macエンジンに接続できません。Launch.commandから起動してください。')}}render();if(P.clips.length)await syncVideo(true);}
$$('.workflow button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});for(let id of ['addMedia','importSide','importMain'])$('#'+id).onclick=()=>$('#filePicker').click();$('#filePicker').onchange=e=>importFiles([...e.target.files]);$('#bgmPicker').onchange=e=>importFiles([...e.target.files],true);$('#projectPicker').onchange=async e=>{try{loadProject(JSON.parse(await e.target.files[0].text()));$('#modal').close()}catch(err){toast(err.message)}e.target.value=''};$('#saveProject').onclick=saveFile;$('#openProject').onclick=openDialog;$('#engineButton').onclick=showEngine;$('#exportButton').onclick=exportDialog;$('#projectName').onchange=e=>mutate(()=>P.name=e.target.value.trim()||'Untitled film');$('#intent').onchange=e=>{mutate(()=>P.intent=e.target.value);toast('解析基準を変更しました。再スキャンで新しい候補を表示します。')};$$('[data-aspect]').forEach(b=>b.onclick=()=>mutate(()=>P.aspect=b.dataset.aspect));$('#play').onclick=play;$('#prevFrame').onclick=()=>step(-1);$('#nextFrame').onclick=()=>step(1);$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$('#setIn').onclick=()=>trimEdge('in');$('#setOut').onclick=()=>trimEdge('out');$('#split').onclick=split;$('#deleteClip').onclick=()=>remove(false);$('#ripple').onclick=()=>remove(true);$('#compare').onpointerdown=()=>{compare=true;draw()};document.addEventListener('pointerup',()=>{if(compare){compare=false;draw()}});$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('#stage').requestFullscreen?.()};$('#timelineZoom').oninput=e=>{zoom=+e.target.value;renderTimeline()};$('#zoomIn').onclick=()=>{zoom=clamp(zoom+.5,1,10);$('#timelineZoom').value=zoom;renderTimeline()};$('#zoomOut').onclick=()=>{zoom=clamp(zoom-.5,1,10);$('#timelineZoom').value=zoom;renderTimeline()};$('#ruler').onpointerdown=e=>{const el=$('#ruler');el.setPointerCapture(e.pointerId);const move=ev=>{let rect=el.getBoundingClientRect();seek((ev.clientX-rect.left)/rect.width*total(P))};move(e);el.onpointermove=move;el.onpointerup=()=>el.onpointermove=null};
function step(direction){let row=locate(P,time);if(!row)return;let c=row.clip,m=mediaOf(c);if(c.gap)return seek(time+direction/30);let s=sourceOffset(time-row.start,c)+direction/(m?.fps||30);seek(row.start+outputOffset(clamp(s,0,c.out-c.in),c));status(m?.rateMode==='VFR'?'VFR素材のフレーム送りは平均FPS基準です。':'フレーム送り')}
function shortcuts(){modal(head('キーボードショートカット')+`<div class="keyboard-grid">${[['再生 / 停止','Space'],['後ろへ1秒','J'],['停止','K'],['前へ1秒','L'],['IN / OUT','I / O'],['分割','S'],['削除・空白を残す','Delete'],['前詰め削除','Shift Delete'],['フレーム送り','← / →'],['元に戻す','⌘ Z'],['やり直し','⌘ Shift Z'],['プロジェクト保存','⌘ S']].map(([a,b])=>`<span>${a}</span><kbd>${b}</kbd>`).join('')}</div><p class="small-note">速度ランプは32区間の積分で近似します。分割時は各区間のカーブを再設定するため、イージングが変わることがあります。</p>`)}$('#shortcuts').onclick=shortcuts;
const keymap={Space:()=>play(),KeyJ:()=>seek(time-1),KeyK:pause,KeyL:()=>seek(time+1),KeyI:()=>trimEdge('in'),KeyO:()=>trimEdge('out'),KeyS:split,ArrowLeft:()=>step(-1),ArrowRight:()=>step(1)};document.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey){if(e.code==='KeyS'){e.preventDefault();saveFile();return}if(e.code==='KeyZ'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();undo(e.shiftKey);return}}if($('#modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||busy)return;if(e.key==='?'){shortcuts();return}if(e.code==='Backspace'||e.code==='Delete'){e.preventDefault();remove(e.shiftKey);return}if(keymap[e.code]){e.preventDefault();keymap[e.code]()}});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dragDepth++;$('#stage').classList.add('dragging')}});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('#stage').classList.remove('dragging')}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();dragDepth=0;$('#stage').classList.remove('dragging');importFiles([...e.dataTransfer.files])}});window.addEventListener('beforeunload',()=>{try{localStorage.setItem('pve.autosave.v1',serial())}catch{}for(let u of urls.values())URL.revokeObjectURL(u);scanWorker?.terminate();painter?.dispose()});$('#modal').addEventListener('cancel',e=>{if(busy){e.preventDefault();toast('処理を止めるには「キャンセル」を押してください。')}});boot();
